    exp_lg[749] = 0;
    exp_lg[750] = 0;
    exp_lg[751] = 0;
    exp_next[46] = 0;
    repeat (3) @(negedge clk);
    checks = checks + 1;
    if (busy !== 1'b0 || done !== 1'b0 || lg_valid !== 1'b0) begin
      $display("TB_FAIL test=reset_init expected_lg=0 got_lg=1");
      $display("TB_RESULT: FAIL");
      $finish;
    end
    rst_n = 1;
    @(negedge clk);
    for (step = 0; step < 46; step = step + 1) begin
      // The prompt comes from the host; after it, the token the
      // hardware chose last step is fed straight back.
      tok = host[step] ? feed[step] : prev;
      pos = step_pos(step);
      if (pos == 0) $write("\n  ");
      if (host[step]) $write("%c", chr[tok]);
      nlg = 0;
      @(negedge clk); start = 1; t0 = cyc;
      @(negedge clk); start = 0;
      while (!done) @(negedge clk);
      span = span + (cyc - t0);
      if (cyc - t0 > lat) lat = cyc - t0;
      checks = checks + 2;
      if (nlg !== 16 || next_tok !== exp_next[step]) begin
        $display("TB_FAIL test=step%0d pos=%0d expected_next=%0d got_next=%0d logits=%0d",
                 step, pos, exp_next[step], next_tok, nlg);
        $display("TB_RESULT: FAIL");
        $finish;
      end
      prev = next_tok;
      // Print what the hardware chose whenever it is kept: fed back
      // as the next token, or the last of a run.
      if (step + 1 == 46 || step_pos(step + 1) == 0 || host[step + 1] == 1'b0)
        $write("%c", chr[next_tok]);
    end
    $display("");
    // Head weights zeroed: all 16 logits are 0, a tie.
    for (i = 19104; i < 19616; i = i + 1) pmem[i] = 0;
    step = 46; nlg = 0; tok = 0; pos = 0;
    @(negedge clk); start = 1;
    @(negedge clk); start = 0;
    while (!done) @(negedge clk);
    checks = checks + 2;
    if (nlg !== 16 || next_tok !== 0) begin
      $display("TB_FAIL test=argmax_tie pos=0 expected_next=0 got_next=%0d logits=%0d",
               next_tok, nlg);
      $display("TB_RESULT: FAIL");
      $finish;
    end
    $display("TB_PROFILE tokens=%0d span_cycles=%0d latency_cycles=%0d",
             46, span, lat);
    $display("TB_PASS checks=%0d", checks);
    $display("TB_RESULT: PASS");
    $finish;
  end

  function integer step_pos(input integer s);
    begin
      case (s)
        0: step_pos = 0;
        1: step_pos = 1;
        2: step_pos = 2;
        3: step_pos = 3;
        4: step_pos = 4;
        5: step_pos = 5;
        6: step_pos = 6;
        7: step_pos = 7;
        8: step_pos = 8;
        9: step_pos = 9;
        10: step_pos = 10;
        11: step_pos = 11;
        12: step_pos = 12;
        13: step_pos = 13;
        14: step_pos = 14;
        15: step_pos = 15;
        16: step_pos = 16;
        17: step_pos = 17;
        18: step_pos = 18;
        19: step_pos = 19;
        20: step_pos = 20;
        21: step_pos = 21;
        22: step_pos = 22;
        23: step_pos = 0;
        24: step_pos = 1;
        25: step_pos = 2;
        26: step_pos = 3;
        27: step_pos = 4;
        28: step_pos = 5;
        29: step_pos = 6;
        30: step_pos = 7;
        31: step_pos = 8;
        32: step_pos = 9;
        33: step_pos = 10;
        34: step_pos = 11;
        35: step_pos = 12;
        36: step_pos = 13;
        37: step_pos = 14;
        38: step_pos = 15;
        39: step_pos = 16;
        40: step_pos = 17;
        41: step_pos = 18;
        42: step_pos = 19;
        43: step_pos = 20;
        44: step_pos = 21;
        45: step_pos = 22;
        default: step_pos = 0;
      endcase
    end
  endfunction
endmodule
